// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation.codegen;

import static org.junit.jupiter.api.Assertions.assertArrayEquals;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertSame;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.Set;

import org.junit.jupiter.api.Test;

/**
 * Unit tests for the shared data structures generated kernels rely on (plan:
 * plans/lmdb-native-engine/19-kernel-ir-primitives.md, M1). Every structure must treat 0 and the -1 unbound sentinel as
 * ordinary keys.
 */
class KernelRuntimeTest {

	@Test
	void longHashSetHandlesZeroMinusOneAndGrowth() {
		KernelRuntime.LongHashSet set = new KernelRuntime.LongHashSet(2);
		assertTrue(set.add(0L));
		assertTrue(set.add(-1L));
		assertFalse(set.add(0L));
		assertFalse(set.add(-1L));
		for (long i = 1; i <= 1000; i++) {
			assertTrue(set.add(i * 7919L));
		}
		assertEquals(1002, set.size());
		assertTrue(set.contains(0L));
		assertTrue(set.contains(-1L));
		assertTrue(set.contains(7919L * 500L));
		assertFalse(set.contains(3L));
	}

	@Test
	void longHashSetAgreesWithJavaUtilOnRandomKeys() {
		Random random = new Random(42);
		KernelRuntime.LongHashSet set = new KernelRuntime.LongHashSet();
		Set<Long> reference = new HashSet<>();
		for (int i = 0; i < 5000; i++) {
			long key = random.nextInt(2000) - 1000;
			assertEquals(reference.add(key), set.add(key), "add mismatch for key " + key);
		}
		assertEquals(reference.size(), set.size());
		for (long key = -1200; key <= 1200; key++) {
			assertEquals(reference.contains(key), set.contains(key), "contains mismatch for key " + key);
		}
	}

	@Test
	void longIntMapAssignsStableInsertionOrdinals() {
		KernelRuntime.LongIntMap map = new KernelRuntime.LongIntMap(2);
		assertEquals(0, map.getOrInsert(42L));
		assertEquals(1, map.getOrInsert(0L));
		assertEquals(2, map.getOrInsert(-1L));
		assertEquals(0, map.getOrInsert(42L));
		assertEquals(1, map.getOrInsert(0L));
		assertEquals(2, map.getOrInsert(-1L));
		assertEquals(3, map.size());
		assertEquals(42L, map.keyAt(0));
		assertEquals(0L, map.keyAt(1));
		assertEquals(-1L, map.keyAt(2));
		assertEquals(-1, map.get(999L));
	}

	@Test
	void longIntMapSurvivesGrowth() {
		KernelRuntime.LongIntMap map = new KernelRuntime.LongIntMap(2);
		for (int i = 0; i < 2000; i++) {
			assertEquals(i, map.getOrInsert(i * 31L + 5L));
		}
		for (int i = 0; i < 2000; i++) {
			assertEquals(i, map.get(i * 31L + 5L));
			assertEquals(i * 31L + 5L, map.keyAt(i));
		}
		assertEquals(2000, map.size());
	}

	@Test
	void rowSetInternsAndDetectsDuplicates() {
		KernelRuntime.RowSet rows = new KernelRuntime.RowSet(3, 2);
		long[] buf = { 1L, 2L, 3L, 1L, 2L, 4L, 1L, 2L, 3L };
		assertEquals(0, rows.addIfAbsent(buf, 0));
		assertEquals(1, rows.addIfAbsent(buf, 3));
		assertEquals(-1, rows.addIfAbsent(buf, 6));
		assertEquals(0, rows.internOrGet(buf, 0));
		assertEquals(2, rows.size());
		assertEquals(4L, rows.value(1, 2));
	}

	@Test
	void rowSetHandlesManyEqualPrefixRows() {
		KernelRuntime.RowSet rows = new KernelRuntime.RowSet(2, 2);
		for (long i = 0; i < 1000; i++) {
			assertEquals((int) i, rows.internOrGet(new long[] { 7L, i }, 0));
		}
		for (long i = 0; i < 1000; i++) {
			assertEquals(-1, rows.addIfAbsent(new long[] { 7L, i }, 0));
		}
		assertEquals(1000, rows.size());
	}

	@Test
	void sortRowsUsesUnsignedOrderAndSupportsDescending() {
		// -1 is unsigned-max, so it must sort last ascending and first descending.
		long[] rows = { 5L, 100L, -1L, 200L, 0L, 300L, 5L, 50L };
		long[] ascending = rows.clone();
		KernelRuntime.sortRows(ascending, 4, 2, new int[] { 0, 1 }, null, null);
		assertArrayRow(ascending, 0, 0L, 300L);
		assertArrayRow(ascending, 1, 5L, 50L);
		assertArrayRow(ascending, 2, 5L, 100L);
		assertArrayRow(ascending, 3, -1L, 200L);
		long[] descending = rows.clone();
		KernelRuntime.sortRows(descending, 4, 2, new int[] { 0 }, new boolean[] { true }, null);
		assertEquals(-1L, descending[0]);
		assertEquals(0L, descending[6]);
	}

	@Test
	void topKMatchesFullSortPrefix() {
		Random random = new Random(7);
		int rowCount = 500;
		int stride = 2;
		long[] rows = new long[rowCount * stride];
		for (int i = 0; i < rows.length; i++) {
			rows[i] = random.nextInt(100);
		}
		long[] fullSort = rows.clone();
		KernelRuntime.sortRows(fullSort, rowCount, stride, new int[] { 0, 1 }, new boolean[] { true, false }, null);
		long[] topK = rows.clone();
		int kept = KernelRuntime.topKRows(topK, rowCount, stride, new int[] { 0, 1 }, new boolean[] { true, false },
				null, 25);
		assertEquals(25, kept);
		List<String> expected = new ArrayList<>();
		List<String> actual = new ArrayList<>();
		for (int r = 0; r < 25; r++) {
			expected.add(fullSort[r * stride] + "," + fullSort[r * stride + 1]);
			actual.add(topK[r * stride] + "," + topK[r * stride + 1]);
		}
		assertEquals(expected, actual);
	}

	private static void assertArrayRow(long[] rows, int row, long col0, long col1) {
		assertEquals(col0, rows[row * 2], "row " + row + " col 0");
		assertEquals(col1, rows[row * 2 + 1], "row " + row + " col 1");
	}

	// ------------------------------------------------------------------
	// Vectorized substrate (plan 23, M1)
	// ------------------------------------------------------------------

	@Test
	void vectorSizeAndIdentityAreConsistent() {
		assertTrue(KernelRuntime.VECTOR_SIZE >= 64, "vector size floor");
		assertEquals(0, KernelRuntime.VECTOR_SIZE % 64, "vector size is a multiple of 64");
		assertEquals(KernelRuntime.VECTOR_SIZE, KernelRuntime.IDENTITY.length);
		for (int i = 0; i < KernelRuntime.IDENTITY.length; i++) {
			assertEquals(i, KernelRuntime.IDENTITY[i]);
		}
	}

	@Test
	void chunkStateStartsDenseAndUnflatThenTakesASelection() {
		KernelRuntime.ChunkState chunk = new KernelRuntime.ChunkState();
		chunk.reset(10);
		assertEquals(10, chunk.size);
		assertEquals(-1, chunk.flatIndex, "a fresh chunk is unflat");
		assertTrue(chunk.isDense(), "a fresh chunk uses the shared identity selection");
		assertSame(KernelRuntime.IDENTITY, chunk.selection);

		int[] scratch = chunk.scratchSelection();
		assertSame(scratch, chunk.scratchSelection(), "scratch is allocated once");
		scratch[0] = 3;
		scratch[1] = 7;
		chunk.select(2);
		assertFalse(chunk.isDense());
		assertEquals(2, chunk.size);
		assertEquals(3, chunk.selection[0]);
		assertEquals(7, chunk.selection[1]);

		chunk.reset(4);
		assertTrue(chunk.isDense(), "reset returns to the identity selection");
		assertEquals(-1, chunk.flatIndex);
	}

	@Test
	void selectEqAndNeAgreeDenseAndSelected() {
		long[] column = { 5L, 7L, 5L, -1L, 0L, 5L };
		int[] target = new int[column.length];

		int kept = KernelRuntime.selectEq(column, column.length, 5L, target);
		assertEquals(3, kept);
		assertArrayEquals(new int[] { 0, 2, 5 }, Arrays.copyOf(target, kept));

		kept = KernelRuntime.selectNe(column, column.length, 5L, target);
		assertEquals(3, kept);
		assertArrayEquals(new int[] { 1, 3, 4 }, Arrays.copyOf(target, kept));

		// Chaining: first keep everything but index 1, then keep the fives among those.
		int[] first = new int[column.length];
		int firstKept = KernelRuntime.selectNe(column, column.length, 7L, first);
		int[] second = new int[column.length];
		int secondKept = KernelRuntime.selectEq(column, first, firstKept, 5L, second);
		assertEquals(3, secondKept);
		assertArrayEquals(new int[] { 0, 2, 5 }, Arrays.copyOf(second, secondKept));
	}

	@Test
	void selectionAwareOverloadsMayWriteInPlace() {
		long[] column = { 1L, 2L, 3L, 4L, 5L, 6L };
		int[] selection = { 0, 1, 2, 3, 4, 5 };
		int kept = KernelRuntime.selectNe(column, selection, selection.length, 3L, selection);
		assertEquals(5, kept);
		assertArrayEquals(new int[] { 0, 1, 3, 4, 5 }, Arrays.copyOf(selection, kept));
	}

	@Test
	void selectRangeUsesUnsignedOrderIncludingTheSentinel() {
		// -1 is the largest unsigned id, 0 the smallest; ordinary signed comparison would get both wrong.
		long[] column = { 0L, 1L, -1L, Long.MIN_VALUE, 42L };
		int[] target = new int[column.length];

		int kept = KernelRuntime.selectRangeUnsigned(column, column.length, 0L, 42L, target);
		assertEquals(3, kept);
		assertArrayEquals(new int[] { 0, 1, 4 }, Arrays.copyOf(target, kept));

		// Long.MIN_VALUE and -1 are both above 42 in unsigned order.
		kept = KernelRuntime.selectRangeUnsigned(column, column.length, 43L, -1L, target);
		assertEquals(2, kept);
		assertArrayEquals(new int[] { 2, 3 }, Arrays.copyOf(target, kept));

		// A single-value range picks out exactly the sentinel.
		kept = KernelRuntime.selectRangeUnsigned(column, column.length, -1L, -1L, target);
		assertEquals(1, kept);
		assertEquals(2, target[0]);
	}

	@Test
	void selectColumnComparisonsAndBoundness() {
		long[] left = { 1L, 2L, 3L, -1L };
		long[] right = { 1L, 9L, 3L, -1L };
		int[] target = new int[left.length];

		int kept = KernelRuntime.selectEqColumns(left, right, left.length, target);
		assertArrayEquals(new int[] { 0, 2, 3 }, Arrays.copyOf(target, kept));

		kept = KernelRuntime.selectNeColumns(left, right, left.length, target);
		assertArrayEquals(new int[] { 1 }, Arrays.copyOf(target, kept));

		kept = KernelRuntime.selectBound(left, left.length, target);
		assertArrayEquals(new int[] { 0, 1, 2 }, Arrays.copyOf(target, kept),
				"the -1 sentinel is unbound and must not survive");

		int[] selection = { 1, 3 };
		kept = KernelRuntime.selectBound(left, selection, selection.length, target);
		assertArrayEquals(new int[] { 1 }, Arrays.copyOf(target, kept));
	}

	@Test
	void gatherBroadcastAndIdentityHelpers() {
		long[] source = { 10L, 11L, 12L, 13L };
		int[] selection = { 3, 0, 2 };
		long[] target = new long[selection.length];
		KernelRuntime.gather(source, selection, selection.length, target);
		assertArrayEquals(new long[] { 13L, 10L, 12L }, target);

		long[] filled = new long[5];
		KernelRuntime.broadcast(filled, 3, -1L);
		assertArrayEquals(new long[] { -1L, -1L, -1L, 0L, 0L }, filled);

		int[] identity = new int[4];
		KernelRuntime.fillIdentity(identity, 4);
		assertArrayEquals(new int[] { 0, 1, 2, 3 }, identity);
	}

	@Test
	void selectPrimitivesAgreeWithAScalarReferenceOnRandomData() {
		Random random = new Random(20260724L);
		int count = 977;
		long[] column = new long[count];
		for (int i = 0; i < count; i++) {
			// Deliberately include 0 and -1 so the sentinel and the empty-slot marker are exercised.
			int pick = random.nextInt(10);
			column[i] = pick == 0 ? 0L : pick == 1 ? -1L : random.nextLong();
		}
		int[] target = new int[count];
		long probe = column[random.nextInt(count)];

		List<Integer> expectedEq = new ArrayList<>();
		List<Integer> expectedBound = new ArrayList<>();
		List<Integer> expectedRange = new ArrayList<>();
		long low = 0L;
		long high = Long.MIN_VALUE; // half the unsigned space
		for (int i = 0; i < count; i++) {
			if (column[i] == probe) {
				expectedEq.add(i);
			}
			if (column[i] != -1L) {
				expectedBound.add(i);
			}
			if (Long.compareUnsigned(column[i], low) >= 0 && Long.compareUnsigned(column[i], high) <= 0) {
				expectedRange.add(i);
			}
		}

		assertEquals(expectedEq, asList(target, KernelRuntime.selectEq(column, count, probe, target)));
		assertEquals(expectedBound, asList(target, KernelRuntime.selectBound(column, count, target)));
		assertEquals(expectedRange,
				asList(target, KernelRuntime.selectRangeUnsigned(column, count, low, high, target)));
	}

	private static List<Integer> asList(int[] selection, int count) {
		List<Integer> positions = new ArrayList<>(count);
		for (int i = 0; i < count; i++) {
			positions.add(selection[i]);
		}
		return positions;
	}
}
